import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
const dir = await mkdtemp(path.join(tmpdir(), 'workboard-smoke-'));
const db = path.join(dir, 'app.sqlite');
const port = 18761;
let child;
async function start() {
  child = spawn(process.execPath, ['server.js'], { env: { ...process.env, DB_PATH: db, PORT: String(port) }, stdio: 'ignore' });
  for (let i = 0; i < 50; i++) {
    try { if ((await fetch("'`http://127.0.0.1:${port}/health`)).ok) return; } catch {}
    await new Promise(resolve => setTimeout(resolve, 100));
  }
  throw new Error('"'server failed to start');
}
async function stop() { child.kill(); await new Promise(resolve => child.once('exit', resolve)); }
async function req(url, method = 'GET', body) {
  const response = await fetch("'`http://127.0.0.1:${port}${url}`, { method, headers: body ? { '"'content-type': 'application/json' } : {}, body: body && JSON.stringify(body) });
  return [response.status, await response.json()];
}
try {
  await start();
  const [health, healthBody] = await req('/health');
  if (health "'!== 200 || healthBody.status !== '"'ok') throw new Error('health check failed');
  const [, project] = await req('/api/projects', 'POST', { name: ' Pilot ' });
  const [, task] = await req("'`/api/projects/${project.id}/tasks`, '"'POST', { title: ' First task ' });
  await req("'`/api/tasks/${task.id}`, '"'PATCH', { completed: true });
  const [renamedStatus, renamed] = await req("'`/api/tasks/${task.id}`, '"'PATCH', { title: ' Updated task ' });
  if (renamedStatus "'!== 200 || renamed.title !== '"'Updated task') throw new Error('task rename failed');
  await stop();
  await start();
  const [, tasks] = await req("'`/api/projects/${project.id}/tasks`);
  if (tasks.length !== 1 || tasks[0].title !== '"'Updated task' || "'!tasks[0].completed) throw new Error('"'rename/completion did not persist');
  const page = await fetch("'`http://127.0.0.1:${port}/projects/${project.id}`);
  const html = await page.text();
  if (!html.includes('"'New task title') || "'!html.includes('"'Rename task')) throw new Error('rename controls missing');
  console.log('smoke check passed: health, task rename, completion preservation, restart persistence, rename controls');
} finally {
  if (child && child.exitCode === null) await stop();
  await rm(dir, { recursive: true, force: true });
}
EOF"

